import csv, datetime

non_product_codes = {'DOT', 'POST', 'M', 'C2', 'D', 'gift_0001_10', 'gift_0001_20', 'gift_0001_30'}

def parse_date(s):
    return datetime.datetime.strptime(s, '%Y-%m-%d %H:%M:%S')

full_rev = {2010: 0.0, 2011: 0.0}
lfl_rev = {2010: 0.0, 2011: 0.0}
# days present in both years
presence = {d: {2010: False, 2011: False} for d in range(1,31)}
with open('transactions.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        dt = parse_date(row['InvoiceDate'])
        if dt.month == 11 and dt.year in (2010,2011):
            presence[dt.day][dt.year] = True

lfl_days = [d for d in range(1,31) if presence[d][2010] and presence[d][2011]]
print("LFL days:", lfl_days)

with open('transactions.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        code = row['StockCode']
        if code in non_product_codes:
            continue
        if 'CHRISTMAS' not in row['Description'].upper():
            continue
        dt = parse_date(row['InvoiceDate'])
        if dt.month == 11 and dt.year in (2010,2011):
            rev = float(row['Quantity']) * float(row['Price'])
            full_rev[dt.year] += rev
            if dt.day in lfl_days:
                lfl_rev[dt.year] += rev

print("Full 2010:", round(full_rev[2010], 2))
print("Full 2011:", round(full_rev[2011], 2))
print("LFL 2010:", round(lfl_rev[2010], 2))
print("LFL 2011:", round(lfl_rev[2011], 2))
print("Diff 2010:", round(full_rev[2010] - lfl_rev[2010], 2))
print("Diff 2011:", round(full_rev[2011] - lfl_rev[2011], 2))
